// Registration order. Later tasks push routes onto their own module; they do not edit this file.
//
// Each module exports { routes: [{ method, path | pattern, access, handler }] }.
// method is an uppercase HTTP verb. path is an exact pathname. pattern is a RegExp;
// capture groups are the handler's params. Provide path or pattern, not both.
// access is 'public', 'session', or 'session-unrestricted'. Until R1-04,
// session-unrestricted is dispatched exactly like session.
// handler(request, response, session, params). Public handlers receive session null.
// Unsafe session methods are checked with requireCsrf before the handler, using the
// X-CSRF-Token header or a JSON csrf_token, same as the existing JSON routes.
// A route may set body: 'raw' to opt out of that JSON parse and its 1 MB cap.
// Raw routes are checked from the X-CSRF-Token header only and read their own body.
module.exports = [
    require('./admin-context'),
    require('./account'),
    require('./preferences'),
    require('./onboarding'),
    require('./users'),
    require('./customer-access'),
    require('./data-ops'),
    require('./imports'),
    require('./partner')
];
